/* Lot 102: colour keyframes on scroll(), view() and scoped named timelines with animation-range (generated by scripts/lot102_gen.py; expectations from scripts/lot102_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[6144];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void prep2(const char *css, int ms, int pm) {
    wf_site_set_scroll(pm);
    prep(css, ms);
    wf_site_set_scroll(0);
    TEST_ASSERT_EQUAL(pm, g_d.scroll_pm);
}

static void test_l102_sheet_0(void) {
    prep2("@property --p { syntax: '<length>'; inherits: false; initial-value: 0px } @keyframes k { 60% { color: color-mix(in srgb, hsl(-0.33rad 100% 87.6% / 50%), lch(none none none/none)); background-color: color-mix(in srgb, oklch(none none none none), color(xyz-d50 0.8 none 0)) } 75% { color: ghostwhite; background-color: hsla(none none none) } } @keyframes j { from { background-color: rgb(144 none none) } 60% { background-color: rgba(none 46% 17% 2) } } body { timeline-scope: all } #i { background-color: blue; animation: k 500ms linear; animation-timeline: --t, scroll(self); animation-range-start: 72%; animation-range-end: -10% } #q { scroll-timeline-name: --t, --u }", 1500, 8200);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#0000ff\"", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_scroll);
    TEST_ASSERT_EQUAL(1, g_d.anim_idle);
    prep2("@property --p { syntax: '<length>'; inherits: false; initial-value: 0px } @keyframes k { from { color: color-mix(in	srgb, 100% forestgreen, rgba(40%, 203, 191.26, 59.8%)) } 33.33% { color: hwb(696.0877 23% 19) } } body { timeline-scope: ALL } #i { animation: k 1000ms, k 1000ms 500ms backwards reverse; animation-timeline: none; animation-range-start: 136.57%, cover, contain, scroll 50%; animation-range-end: 88% , scroll 50% }", 1500, 10000);
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_scroll);
    TEST_ASSERT_EQUAL(2, g_d.anim_idle);
    prep2("@property --p { syntax: '<length>'; inherits: false; initial-value: 0px } @keyframes k { to { color: color-mix(in srgb, hsl(none, 10%, 20%), hsl(none, 10%, 20%)) } } @keyframes j { from { background-color: color(srgb-linear none 0.612 none) } } html { scroll-timeline: --t } body { scroll-timeline-name: --v, --t; scroll-timeline-axis: y } #o { timeline-scope: ALL } #i { background-color: rebeccapurple; animation: j 500ms linear; animation-timeline: --t, scroll(self); animation-range: 52%, -31.21% exit; animation-composition: accumulate }", 500, 5000);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#663399\"", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_scroll);
    TEST_ASSERT_EQUAL(1, g_d.anim_idle);
    prep2("@property --p { syntax: '<length>'; inherits: false; initial-value: 0px } @keyframes k { 60% { background-color: darksalmon } 75% { color: rgb(256, 144, 25); background-color: lab(5.428 100% 100% /none) } } body { scroll-timeline-name: --u; scroll-timeline-axis: y, block; timeline-scope: --t } #i { color: hsla(1turn 26% 82%); background-color: #fc3f; animation: k 1000ms linear infinite; animation-timeline: view(block 10%); animation-range: 66% 12.5%, entry-crossing 119.72% -36%, 105.99%, 50% }", 0, 590);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#ddc5c5;background-color:#ffcc33\"", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_scroll);
    TEST_ASSERT_EQUAL(1, g_d.anim_idle);
}

